INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845PDHQFC3XGEQ68S5QYXCR', 'epic', NULL, 'Text selection & clipboard layer', 'Right-click context menus, visible/draggable text selection, and copy-from-anywhere are missing app-wide because clide ships no Material and never rebuilt the layer Material''s TextField supplies. See D-109.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:27.629', '2026-09-08 17:35:27.629', NULL, '9b71bd3a029d24fcbba827e983d8bafc', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845PXTGB6PKKRMCC614P2RC', 'story', '06G845PDHQFC3XGEQ68S5QYXCR', 'ClideTextContextMenu — pointer-anchored menu primitive', 'Show a ClideMenu at a global pointer position via ContextMenuController: root-overlay insert, tap-away barrier, Escape dismiss, and edge-flip so the menu never runs off the viewport. Anchors to a point, not a widget, so it cannot reuse ClideAnchoredOverlay''s LayerLink path.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:31.796', '2026-09-08 17:35:31.796', NULL, 'b7543a8559efe522f71ac483bdcbc556', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845QBAC9SA9V90R7Q6BY1S0', 'story', '06G845PDHQFC3XGEQ68S5QYXCR', 'ClideEditable — themed selection, drag-select, context menu', 'Wrap EditableText with a themed selectionColor (only the code editor sets one today), a TextSelectionGestureDetectorBuilder for drag / double-tap-word / triple-tap-line selection, and a cut/copy/paste/select-all context menu. Drop-in API covering the props the 17 call sites actually use.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:35.251', '2026-09-08 17:35:35.251', NULL, '65c1fe5acc02b84d4f14503cb8af658e', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845QPVQWAARNGX951ZMN7C8', 'story', '06G845PDHQFC3XGEQ68S5QYXCR', 'Migrate all EditableText call sites to ClideEditable', '17 sites across 14 files: composer, palette, filter box, quick-open, ex-line, git commit box, welcome, settings, ask box, team chat, inject field, prompt card, path preset, file actions, code editor. Add a test asserting no bare EditableText remains under lib/.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:38.205', '2026-09-08 17:35:38.205', NULL, '0035dbd54958e50456366366608da05f', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845R1ZRAZJ1V771N975HFXG', 'story', '06G845PDHQFC3XGEQ68S5QYXCR', 'Context menu + copy on ClideSelectionArea', 'Give ClideSelectionArea a contextMenuBuilder so right-click over selected read-only prose offers Copy / Select all. Covers the conversation view and the team panel today, and every surface story T-582 adds.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:41.054', '2026-09-08 17:35:41.054', NULL, 'f837909fbbdd4fe30800834186ee05d1', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845RHZ4JB3SQNQBFTVQ383G', 'story', '06G845PDHQFC3XGEQ68S5QYXCR', 'Make read-only prose surfaces selectable', 'ClideSelectionArea is used in exactly two places today (conversation view, team panel). The markdown viewer, decision detail and ticket detail render ClideMarkdown bare — no SelectableRegion above them, so there is no selection to copy. Wrap them.', 'backlog', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:45.146', '2026-09-08 17:35:45.146', NULL, 'ce50b33b2077e2a560a99a1df25e54a7', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
