INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G845PDHQFC3XGEQ68S5QYXCR', 'epic', NULL, 'Text selection & clipboard layer', 'Right-click context menus, visible/draggable text selection, and copy-from-anywhere are missing app-wide because clide ships no Material and never rebuilt the layer Material''s TextField supplies. See D-109.', 'done', 'high', NULL, NULL, 'D-109', '2026-09-08 17:35:27.629', '2026-09-09 06:27:10.917', NULL, 'fd3eb2761ac1aece8502baaa7e35f337', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G89XGF4AFJXVDXNH6X8C7B5G', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'clide clipboard set/history CLI verbs', 'The clipboard is UI-only: kernel ClideClipboard exists with writePlain/readPlain/history and OS sync, but no dispatcher verb exposes it, so D-6 parity is broken. Add clipboard.set (with a toast, since overwriting a paste buffer must not be silent) and clipboard.history. No read verb by design — the user''s clipboard holds secrets.', 'backlog', 'high', NULL, NULL, 'D-6', '2026-09-09 06:58:33.378', '2026-09-09 06:58:33.378', NULL, 'd9a186c510219e0092bb7966ee1edbf2', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G89XGF4AFJXVDXNH6X8C7B5G', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'clide clipboard set/history CLI verbs', 'The clipboard is UI-only: kernel ClideClipboard exists with writePlain/readPlain/history and OS sync, but no dispatcher verb exposes it, so D-6 parity is broken. Add clipboard.set (with a toast, since overwriting a paste buffer must not be silent) and clipboard.history. No read verb by design — the user''s clipboard holds secrets.', 'done', 'high', NULL, NULL, 'D-6', '2026-09-09 06:58:33.378', '2026-09-09 07:09:25.461', NULL, '9de9cc66608dbf9d396ac83158edbedd', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G8AA5V21410GE02SR26EPD6W', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'Injected agent note duplicated a stale subsystem list', 'clideContextNote hardcoded ''subsystems that respond today: files, editor, git, search, pql, panel/pane'' while 16 dispatched, so a hosted session read the other nine (clipboard, ui, image, icon, canvas, project, env, log, claude) as not existing. A second copy of the command registry that nothing forces anyone to update, failing silently toward hiding features. Replace with a pointer to clide capabilities, which is generated from the live registry.', 'backlog', 'high', NULL, NULL, 'D-6', '2026-09-09 07:53:54.192', '2026-09-09 07:53:54.192', NULL, 'e6c98323e7b951de734ea30a2bf4b59d', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G8AA5V21410GE02SR26EPD6W', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'Injected agent note duplicated a stale subsystem list', 'clideContextNote hardcoded ''subsystems that respond today: files, editor, git, search, pql, panel/pane'' while 16 dispatched, so a hosted session read the other nine (clipboard, ui, image, icon, canvas, project, env, log, claude) as not existing. A second copy of the command registry that nothing forces anyone to update, failing silently toward hiding features. Replace with a pointer to clide capabilities, which is generated from the live registry.', 'done', 'high', NULL, NULL, 'D-6', '2026-09-09 07:53:54.192', '2026-09-09 07:55:04.241', NULL, '2dd8628ff56f1654774a543e174c932c', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCSTYAH54YEBZ4JE3ABQW4B8', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'Status bar empty before first turn; /login unusable in clide', 'Status bar showed no model/mode until the first turn (init event only arrives with a turn); now seeded from the initialize handshake. /login was a TUI-only notice and the account sign-in dialog ran ''claude login'', which the CLI parses as a prompt; now ''claude auth login'' in a dialog + respawn.', 'backlog', 'medium', NULL, NULL, NULL, '2026-09-23 06:20:00.009', '2026-09-23 06:20:00.009', NULL, '57a87c7570f66b9cea87733e720496a0', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCSTYAH54YEBZ4JE3ABQW4B8', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'Status bar empty before first turn; /login unusable in clide', 'Status bar showed no model/mode until the first turn (init event only arrives with a turn); now seeded from the initialize handshake. /login was a TUI-only notice and the account sign-in dialog ran ''claude login'', which the CLI parses as a prompt; now ''claude auth login'' in a dialog + respawn.', 'done', 'medium', NULL, NULL, NULL, '2026-09-23 06:20:00.009', '2026-09-23 06:20:01.655', NULL, 'a65b8d98b2a76f195d3fe08f721f25d4', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FB0TNQM6DH7C6GQN9WNKQNXR', 'bug', NULL, 'pane list omits the loaded subject — CLI can''t tell which ticket/decision/file a detail pane shows', '`clide pane list` reports every GUI tab (T-219, D-83) but only its generic chrome: `id`, `title`, `active`, `visible`. For the context-slot detail panes the title is a static word — `tickets.detail` → "Ticket", `decisions.detail` → "Decision", `editor.active` → "Editor" — so the CLI cannot tell *which* ticket / decision / file the pane currently shows. The loaded subject lives in the view''s reader-nav state and never reaches the wire.
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FB0TNQM6DH7C6GQN9WNKQNXR', 'bug', NULL, 'pane list omits the loaded subject — CLI can''t tell which ticket/decision/file a detail pane shows', '`clide pane list` reports every GUI tab (T-219, D-83) but only its generic chrome: `id`, `title`, `active`, `visible`. For the context-slot detail panes the title is a static word — `tickets.detail` → "Ticket", `decisions.detail` → "Decision", `editor.active` → "Editor" — so the CLI cannot tell *which* ticket / decision / file the pane currently shows. The loaded subject lives in the view''s reader-nav state and never reaches the wire.
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCSWVHN0QF86TPSEFGW2JXFW', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'Claude pane: show messages sent mid-turn as queued, and let them be dismissed', NULL, 'backlog', 'medium', NULL, NULL, 'D-78', '2026-09-23 06:28:21.544', '2026-09-23 06:28:21.544', NULL, 'f180d8c3326d774142059be49d3be9ea', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCSWVHN0QF86TPSEFGW2JXFW', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'Claude pane: show messages sent mid-turn as queued, and let them be dismissed', 'A message sent from the Claude composer while a turn is still running is queued by the CLI, but clide renders it as an ordinary user turn — the user can''t tell it hasn''t been picked up yet, and can''t take it back.
